{"content": "1|// Parser for `ofxPropsMetadata.h`, implemented per ./INSTRUCTIONS.md.
2|//
3|// The grammar mirrors the `Structure` schema in ../types.ts one-to-one: every
4|// element of the expected structure corresponds to exactly one parser rule,
5|// and the rules appear in exactly the order the structure tuple prescribes.
6|// Anything the header adds, removes, or reorders therefore fails the parse.
7|// Regions whose contents do not contribute to the result (struct bodies,
8|// template parameter lists, static_assert expressions) are consumed through
9|// token-category "soup" rules that are still bracket-delimited and strict
10|// about the surrounding shape.
11|
12|import { createToken, CstParser, EOF, Lexer } from "chevrotain";
13|import type { TokenType } from "chevrotain";
14|import {
15|  fail,
16|  Include,
17|  lexingError,
18|  makeHeaderLexer,
19|  parseCppString,
20|  parsingError,
21|  PragmaOnce,
22|  toInt,
23|} from "../../common-by-llms/mod.ts";
24|import type { LexIssue, ParseIssue } from "../../common-by-llms/mod.ts";
25|import { PropType as PropTypeSchema } from "../types.ts";
26|import type { FinalResult, PropType, Result, Structure } from "../types.ts";
27|
28|/** The canonical PropType set, taken from ../types.ts (single source of truth). */
29|const PROP_TYPES = new Set<string>(PropTypeSchema.options);
30|
31|// ---------------------------------------------------------------------------
32|// Tokens
33|// ---------------------------------------------------------------------------
34|
35|// --- skipped by the lexer ---------------------------------------------------
36|// Trivia tokens live in ../../common-by-llms (shared with the other header
37|// parsers) and are re-exported here only as needed by the token lists below.
38|
39|// --- token categories -------------------------------------------------------
40|// Categories let the grammar consume "any token except X" inside regions whose
41|// exact contents do not contribute to the result. Membership is deliberately
42|// narrow: tokens that would indicate a structural surprise (e.g. a `namespace`
43|// keyword inside a struct body) are not members of any category, so their
44|// appearance there is a parse error.
45|
46|const AnyExceptBrace = createToken({
47|  name: "AnyExceptBrace",
48|  pattern: Lexer.NA,
49|});
50|const AnyExceptParenOrSemicolon = createToken({
51|  name: "AnyExceptParenOrSemicolon",
52|  pattern: Lexer.NA,
53|});
54|const AnyExceptAngleOrComma = createToken({
55|  name: "AnyExceptAngleOrComma",
56|  pattern: Lexer.NA,
57|});
58|
59|const soupEverywhere = [
60|  AnyExceptBrace,
61|  AnyExceptParenOrSemicolon,
62|  AnyExceptAngleOrComma,
63|];
64|const soupBraceAndParen = [AnyExceptBrace, AnyExceptParenOrSemicolon];
65|const soupBraceAndTemplate = [AnyExceptBrace, AnyExceptAngleOrComma];
66|
67|// --- preprocessor -----------------------------------------------------------
68|
69|// `#pragma once`, includes and trivia come from ../../common-by-llms. This
70|// dialect additionally allows a whole `#define ...` directive including
71|// backslash-newline continuations (a newline may only appear escaped).
72|const DefineDirective = createToken({
73|  name: "DefineDirective",
74|  pattern: /#define(?:[^\\\n\r]|\\[\s\S])*/,
75|});
76|
77|// --- keywords ---------------------------------------------------------------
78|// Keywords that may legitimately appear inside skipped regions carry the
79|// corresponding soup categories; the rest do not.
80|
81|const NamespaceKW = createToken({
82|  name: "NamespaceKW",
83|  pattern: /namespace\b/,
84|});
85|const EnumKW = createToken({ name: "EnumKW", pattern: /enum\b/ });
86|const ClassKW = createToken({ name: "ClassKW", pattern: /class\b/ });
87|const StructKW = createToken({ name: "StructKW", pattern: /struct\b/ });
88|const UsingKW = createToken({ name: "UsingKW", pattern: /using\b/ });
89|const StaticAssertKW = createToken({
90|  name: "StaticAssertKW",
91|  pattern: /static_assert\b/,
92|});
93|const StaticKW = createToken({
94|  name: "StaticKW",
95|  pattern: /static\b/,
96|  categories: soupEverywhere,
97|});
98|const InlineKW = createToken({
99|  name: "InlineKW",
100|  pattern: /inline\b/,
101|  categories: soupEverywhere,
102|});
103|const ConstexprKW = createToken({
104|  name: "ConstexprKW",
105|  pattern: /constexpr\b/,
106|  categories: soupEverywhere,
107|});
108|const ConstKW = createToken({
109|  name: "ConstKW",
110|  pattern: /const\b/,
111|  categories: soupEverywhere,
112|});
113|const TemplateKW = createToken({
114|  name: "TemplateKW",
115|  pattern: /template\b/,
116|  categories: soupEverywhere,
117|});
118|const TypenameKW = createToken({
119|  name: "TypenameKW",
120|  pattern: /typename\b/,
121|  categories: soupEverywhere,
122|});
123|
124|// --- fixed multi-word symbols ------------------------------------------------
125|// `PropType` may appear inside skipped regions (e.g. struct fields), so it
126|// carries soup categories too; the namespace/variable names do not.
127|
128|const OpenfxSpan = createToken({
129|  name: "OpenfxSpan",
130|  pattern: /openfx::span\b/,
131|  categories: soupEverywhere,
132|});
133|const StdArray = createToken({
134|  name: "StdArray",
135|  pattern: /std::array\b/,
136|  categories: soupEverywhere,
137|});
138|const PropTypeKW = createToken({
139|  name: "PropTypeKW",
140|  pattern: /PropType\b/,
141|  categories: soupEverywhere,
142|});
143|const OpenfxNS = createToken({ name: "OpenfxNS", pattern: /openfx\b/ });
144|const PropEnumValuesNS = createToken({
145|  name: "PropEnumValuesNS",
146|  pattern: /prop_enum_values\b/,
147|});
148|const PropTypeArraysNS = createToken({
149|  name: "PropTypeArraysNS",
150|  pattern: /prop_type_arrays\b/,
151|});
152|const PropertiesNS = createToken({
153|  name: "PropertiesNS",
154|  pattern: /properties\b/,
155|});
156|const AssertionsNS = createToken({
157|  name: "AssertionsNS",
158|  pattern: /assertions\b/,
159|});
160|const PropDefsVar = createToken({
161|  name: "PropDefsVar",
162|  pattern: /prop_defs\b/,
163|});
164|const DefinePropTraitsKW = createToken({
165|  name: "DefinePropTraitsKW",
166|  pattern: /DEFINE_PROP_TRAITS\b/,
167|});
168|
169|// --- punctuation and literals ------------------------------------------------
170|
171|const LBrace = createToken({ name: "LBrace", pattern: /\{/ });
172|const RBrace = createToken({ name: "RBrace", pattern: /\}/ });
173|const LParen = createToken({
174|  name: "LParen",
175|  pattern: /\(/,
176|  categories: soupBraceAndTemplate,
177|});
178|const RParen = createToken({
179|  name: "RParen",
180|  pattern: /\)/,
181|  categories: soupBraceAndTemplate,
182|});
183|const LBracket = createToken({
184|  name: "LBracket",
185|  pattern: /\[/,
186|  categories: soupEverywhere,
187|});
188|const RBracket = createToken({
189|  name: "RBracket",
190|  pattern: /\]/,
191|  categories: soupEverywhere,
192|});
193|const Less = createToken({
194|  name: "Less",
195|  pattern: /</,
196|  categories: soupBraceAndParen,
197|});
198|const Greater = createToken({
199|  name: "Greater",
200|  pattern: />/,
201|  categories: soupBraceAndParen,
202|});
203|const Semicolon = createToken({
204|  name: "Semicolon",
205|  pattern: /;/,
206|  categories: soupBraceAndTemplate,
207|});
208|const Comma = createToken({
209|  name: "Comma",
210|  pattern: /,/,
211|  categories: soupBraceAndParen,
212|});
213|const Equals = createToken({
214|  name: "Equals",
215|  pattern: /=/,
216|  categories: soupEverywhere,
217|});
218|const EqEq = createToken({
219|  name: "EqEq",
220|  pattern: /==/,
221|  categories: soupEverywhere,
222|});
223|const Star = createToken({
224|  name: "Star",
225|  pattern: /\*/,
226|  categories: soupEverywhere,
227|});
228|const Amp = createToken({
229|  name: "Amp",
230|  pattern: /&/,
231|  categories: soupEverywhere,
232|});
233|const Dot = createToken({
234|  name: "Dot",
235|  pattern: /\./,
236|  categories: soupEverywhere,
237|});
238|const ScopeRes = createToken({
239|  name: "ScopeRes",
240|  pattern: /::/,
241|  categories: soupEverywhere,
242|});
243|const StringLiteral = createToken({
244|  name: "StringLiteral",
245|  pattern: /"(?:[^"\\\n\r]|\\.)*"/,
246|  categories: soupEverywhere,
247|});
248|const NumberLiteral = createToken({
249|  name: "NumberLiteral",
250|  pattern: /\d+/,
251|  categories: soupEverywhere,
252|});
253|const Identifier = createToken({
254|  name: "Identifier",
255|  pattern: /[A-Za-z_][A-Za-z0-9_]*/,
256|  categories: soupEverywhere,
257|});
258|
259|const dialectTokens: TokenType[] = [
260|  // `#define` is specific to this dialect (the DEFINE_PROP_TRAITS macro).
261|  DefineDirective,
262|  // Longer keywords before shorter prefixes and before Identifier.
263|  StaticAssertKW,
264|  EqEq,
265|  ScopeRes,
266|  ConstexprKW,
267|  NamespaceKW,
268|  EnumKW,
269|  ClassKW,
270|  StructKW,
271|  StaticKW,
272|  InlineKW,
273|  ConstKW,
274|  UsingKW,
275|  TemplateKW,
276|  TypenameKW,
277|  OpenfxSpan,
278|  StdArray,
279|  PropTypeKW,
280|  OpenfxNS,
281|  PropEnumValuesNS,
282|  PropTypeArraysNS,
283|  PropertiesNS,
284|  AssertionsNS,
285|  PropDefsVar,
286|  DefinePropTraitsKW,
287|  LBrace,
288|  RBrace,
289|  LParen,
290|  RParen,
291|  LBracket,
292|  RBracket,
293|  Less,
294|  Greater,
295|  Semicolon,
296|  Comma,
297|  Equals,
298|  Star,
299|  Amp,
300|  Dot,
301|  StringLiteral,
302|  NumberLiteral,
303|  Identifier,
304|];
305|const parserTokens = [
306|  ...dialectTokens,
307|  PragmaOnce,
308|  Include,
309|  AnyExceptBrace,
310|  AnyExceptParenOrSemicolon,
311|  AnyExceptAngleOrComma,
312|];
313|
314|const ofxLexer = makeHeaderLexer(dialectTokens);
315|
316|// ---------------------------------------------------------------------------
317|// Parser
318|// ---------------------------------------------------------------------------
319|
320|type OpenfxInner = Structure[2]["inner"];
321|type OpenfxInnerElement = OpenfxInner[number];
322|type PropertiesInner = Extract<
323|  OpenfxInnerElement,
324|  { type: "namespace:properties" }
325|>["inner"];
326|type AssertionsInner = Extract<
327|  OpenfxInnerElement,
328|  { type: "namespace:assertions" }
329|>["inner"];
330|
331|class OfxPropsMetadataParser extends CstParser {
332|  // --- collected data ---------------------------------------------------------
333|
334|  readonly propEnumValues: Record<string, Set<string>> = {};
335|  readonly propTypeArrays: Record<string, Set<PropType>> = {};
336|  readonly propDefsArray: Record<string, { dimension: number }[]> = {};
337|  /** Ids of DEFINE_PROP_TRAITS calls, in header order. */
338|  readonly propTraitsCallIds: string[] = [];
339|  /** Members of the `enum class PropId` (excluding the trailing NProps). */
340|  readonly propIdNames: string[] = [];
341|
342|  // --- structure markers ------------------------------------------------------
343|  // Pushed by each section rule, in exactly the order the grammar enforces.
344|
345|  readonly openfxInner: OpenfxInnerElement[] = [];
346|  readonly propertiesInner: PropertiesInner[number][] = [];
347|  readonly assertionsInner: AssertionsInner[number][] = [];
348|
349|  constructor() {
350|    super(parserTokens);
351|    this.performSelfAnalysis();
352|  }
353|
354|  // header: `#pragma once`, includes, then the single `openfx` namespace.
355|  headerFile = this.RULE("headerFile", () => {
356|    this.CONSUME(PragmaOnce);
357|    this.AT_LEAST_ONE(() => this.CONSUME(Include));
358|    this.SUBRULE(this.namespaceOpenfx);
359|    this.CONSUME(EOF);
360|  });
361|
362|  namespaceOpenfx = this.RULE("namespaceOpenfx", () => {
363|    this.CONSUME(NamespaceKW);
364|    this.CONSUME(OpenfxNS);
365|    this.CONSUME(LBrace);
366|    this.SUBRULE(this.enumPropType);
367|    this.SUBRULE(this.enumPropId);
368|    this.SUBRULE(this.namespacePropEnumValues);
369|    this.SUBRULE(this.namespacePropTypeArrays);
370|    this.SUBRULE(this.structPropDef);
371|    this.SUBRULE(this.templateStructPropDefsArray);
372|    this.SUBRULE(this.staticPropDefs);
373|    this.SUBRULE(this.namespaceProperties);
374|    this.SUBRULE(this.namespaceAssertions);
375|    this.CONSUME(RBrace);
376|  });
377|
378|  // `enum class PropType { Int, Double, Enum, Bool, String, Pointer };`
379|  enumPropType = this.RULE("enumPropType", () => {
380|    this.CONSUME(EnumKW);
381|    this.CONSUME(ClassKW);
382|    this.CONSUME(PropTypeKW);
383|    this.CONSUME(LBrace);
384|    const enumerators: string[] = [];
385|    const first = this.CONSUME(Identifier);
386|    this.ACTION(() => enumerators.push(first.image));
387|    this.MANY(() => {
388|      this.CONSUME(Comma);
389|      const next = this.CONSUME2(Identifier);
390|      this.ACTION(() => enumerators.push(next.image));
391|    });
392|    this.CONSUME(RBrace);
393|    this.CONSUME(Semicolon);
394|    this.ACTION(() => {
395|      // The grammar rule only sees identifiers; validate that the enumerator
396|      // set is exactly the canonical PropType set (order-insensitive).
397|      const actual = new Set(enumerators);
398|      if (
399|        actual.size !== PROP_TYPES.size ||
400|        enumerators.some((e) => !PROP_TYPES.has(e))
401|      ) {
402|        fail(
403|          `enum PropType enumerators ${JSON.stringify(enumerators)} do not ` +
404|            `match the canonical PropType set ${
405|              JSON.stringify([...PROP_TYPES])
406|            }`,
407|        );
408|      }
409|      this.openfxInner.push("enum:propType");
410|    });
411|  });
412|
413|  // `enum class PropId { ... };` -- only the member names matter (they are
414|  // the ids referenced by DEFINE_PROP_TRAITS).
415|  enumPropId = this.RULE("enumPropId", () => {
416|    this.CONSUME(EnumKW);
417|    this.CONSUME(ClassKW);
418|    const name = this.CONSUME(Identifier);
419|    this.ACTION(() => {
420|      if (name.image !== "PropId") {
421|        fail(`expected enum name "PropId" but got "${name.image}"`);
422|      }
423|    });
424|    this.CONSUME(LBrace);
425|    const first = this.CONSUME2(Identifier);
426|    this.ACTION(() => this.propIdNames.push(first.image));
427|    this.MANY(() => {
428|      this.CONSUME(Comma);
429|      const next = this.CONSUME3(Identifier);
430|      this.ACTION(() => this.propIdNames.push(next.image));
431|    });
432|    this.CONSUME(RBrace);
433|    this.CONSUME(Semicolon);
434|    this.ACTION(() => {
435|      const sentinel = this.propIdNames.pop();
436|      if (sentinel !== "NProps") {
437|        fail(
438|          `expected the PropId enum to end with the "NProps" sentinel but got "${
439|            sentinel ?? "<none>"
440|          }"`,
441|        );
442|      }
443|      if (new Set(this.propIdNames).size !== this.propIdNames.length) {
444|        fail("duplicate members in the PropId enum");
445|      }
446|    });
447|    this.ACTION(() => this.openfxInner.push("enum:propId"));
448|  });
449|
450|  // namespace prop_enum_values { constexpr std::array X = {...}; ... }
451|  namespacePropEnumValues = this.RULE("namespacePropEnumValues", () => {
452|    this.CONSUME(NamespaceKW);
453|    this.CONSUME(PropEnumValuesNS);
454|    this.CONSUME(LBrace);
455|    this.MANY(() => this.SUBRULE(this.enumValuesDecl));
456|    this.CONSUME(RBrace);
457|    this.ACTION(() => this.openfxInner.push("namespace:propEnumValues"));
458|  });
459|
460|  enumValuesDecl = this.RULE("enumValuesDecl", () => {
461|    this.CONSUME(ConstexprKW);
462|    this.CONSUME(StdArray);
463|    const nameTok = this.CONSUME(Identifier);
464|    this.CONSUME(Equals);
465|    this.CONSUME(LBrace);
466|    const values: string[] = [];
467|    const first = this.CONSUME(StringLiteral);
468|    this.ACTION(() => values.push(parseCppString(first.image)));
469|    this.MANY(() => {
470|      this.CONSUME(Comma);
471|      const next = this.CONSUME2(StringLiteral);
472|      this.ACTION(() => values.push(parseCppString(next.image)));
473|    });
474|    this.CONSUME(RBrace);
475|    this.CONSUME(Semicolon);
476|    this.ACTION(() => {
477|      const name = nameTok.image;
478|      if (name in this.propEnumValues) {
479|        fail(`duplicate prop_enum_values entry "${name}"`);
480|      }
481|      this.propEnumValues[name] = new Set(values);
482|    });
483|  });
484|
485|  // namespace prop_type_arrays { static constexpr PropType X_types[] = {...}; ... }
486|  namespacePropTypeArrays = this.RULE("namespacePropTypeArrays", () => {
487|    this.CONSUME(NamespaceKW);
488|    this.CONSUME(PropTypeArraysNS);
489|    this.CONSUME(LBrace);
490|    this.MANY(() => this.SUBRULE(this.typeArrayDecl));
491|    this.CONSUME(RBrace);
492|    this.ACTION(() => this.openfxInner.push("namespace:propTypeArrays"));
493|  });
494|
495|  typeArrayDecl = this.RULE("typeArrayDecl", () => {
496|    this.CONSUME(StaticKW);
497|    this.CONSUME(ConstexprKW);
498|    this.CONSUME(PropTypeKW);
499|    const nameTok = this.CONSUME(Identifier);
500|    this.CONSUME(LBracket);
