{"content": "1|import path from "node:path";
2|
3|import { assert } from "@std/assert";
4|import { parseArgs } from "@std/cli/parse-args";
5|
6|import { makeFinalResult, parse } from "./impl-by-llms/mod.ts";
7|import { FinalResult, PropertyInfos, Structure } from "./types.ts";
8|
9|const args = parseArgs(Deno.args, {
10|  string: ["crate-path"],
11|});
12|
13|if (!args["crate-path"]) throw new Error("Missing `--crate-path`");
14|
15|const headerPath = path.join(
16|  args["crate-path"],
17|  "vendor",
18|  "openfx",
19|  "openfx-cpp",
