  // Enum + Int on an enum-only array.
  const enumAdded = structuredClone(result);
  findTypeArray(enumAdded, (t) => t.has("Enum"))[1].add("Int");
  assertThrows(() => makeFinalResult(enumAdded), Error, `mixes "Enum"`);

